for(const [id,title,tag,ic,ms,project,credential,daily] of roleAdditions)roles.push({id,title,tag,icon:ic,modules:ms,project,credential,daily,desc:daily,skills:id.startsWith('ml')||id==='ailead'?['Adjacent career','Data provenance','Evaluation','Governance']:['System reasoning','Evidence','Collaboration','Risk'],milestones:[`Build the shared systems, identity, networking, and risk foundation for ${title.toLowerCase()} work.`,`Study the linked modules and compare ${title.toLowerCase()} tasks across current job descriptions.`,`Adapt the suggested project to demonstrate a narrow, reproducible skill with synthetic or approved data.`,`Explain assumptions, limitations, and handovers; advanced and leadership roles also require substantial relevant experience.`]});
const challenges=[
{title:'Navigate a synthetic Linux workspace',module:'linux',action:'#field/terminal',task:'Use pwd, ls, cd, and cat in the browser simulation. Read the lab’s scope note.',evidence:'Record the current directory, the permitted files, and the stated authorization boundary.'},
{title:'Check a lab network diagram',module:'labsetup',task:'Draw learner and target guests with an internal-only segment. Explain how host-only, NAT, and bridged modes differ.',evidence:'Show a permitted flow and an unintended flow that must fail.'},
{title:'Interpret a service inventory',module:'assessment',action:'#field/scan',task:'Read the synthetic port-state table and choose a justified next step.',evidence:'Distinguish observation, applicability evidence, and remediation.'},
{title:'Trace one HTTP request',module:'webdepth',task:'In a provider-hosted beginner lab, identify method, path, parameters, and response status.',evidence:'Explain which fields are client input and where authorization must happen.'},
{title:'Compare two injection boundaries',module:'webdepth',task:'Study SQL injection and XSS notes in the Academy. Compare interpreter, impact, and root-cause fix.',evidence:'Write two prevention-oriented regression-test descriptions.'},
{title:'Review object ownership',module:'webdepth',task:'Describe a fictional student-record endpoint and its denied-access behavior.',evidence:'Specify the server-side ownership decision and an unauthorized-user test.'},
{title:'Threat-model an upload',module:'webdepth',task:'Map upload validation, storage, execution, paths, and download permissions.',evidence:'Propose one test for path handling and one for authorization.'},
{title:'Investigate a synthetic sign-in',module:'defense',action:'#labs/triage',task:'Review the provided events and choose an evidence-based response.',evidence:'Write a timeline, a benign alternative explanation, and the next evidence to request.'},
{title:'Model an authentication throttle',module:'credentialaudit',action:'#field/throttle',task:'Compare allowed and throttled events for a predefined sequence. Send no network requests.',evidence:'Describe a threshold tradeoff and one limitation of the toy model.'},
{title:'Write a responsible finding',module:'professional',action:'#project/appsec',task:'Create a scoped, synthetic assessment report and a private disclosure plan.',evidence:'Include impact, evidence, mitigation, retest, and cleanup without secrets.'}
];
const glossary=[
['APT','A threat actor or campaign characterized by sustained objectives and resources; attribution needs evidence.'],['CIA triad','Confidentiality, integrity, and availability: distinct goals for protecting an asset.'],['C2','Command and control: communication used to direct compromised systems.'],['CVE','A public identifier for a specific disclosed vulnerability.'],['CWE','A category of software or hardware weakness; distinct from a specific CVE.'],['CVSS','A structured vulnerability-severity score; context and business impact still determine risk.'],['EDR / XDR','Endpoint or extended detection and response: telemetry, analysis, and response workflows.'],['IDS / IPS','Intrusion detection observes and alerts; prevention may also interrupt traffic.'],['IOC','An indicator associated with possible compromise; a match requires context.'],['Lateral movement','Moving from one affected system or identity to another.'],['MFA','Authentication using independent factor categories, rather than two secrets of the same kind.'],['Privilege escalation','Gaining authority beyond the access initially available.'],['Ransomware','Malicious activity that can deny access to systems or data and demand payment; impacts may include theft.'],['SIEM','Security information and event management: collecting and correlating event data.'],['SOAR','Security orchestration, automation, and response: coordinating response workflows.'],['SOC','Security operations center: people and processes that monitor, investigate, and respond.'],['Threat intelligence','Contextual analysis that helps answer a specific defensive decision.'],['Zero-day','A previously unknown or unpatched vulnerability, with exact usage depending on context.'],['Zero Trust','Explicit, limited, context-aware access rather than broad trust based on location.'],['WAF','A web application firewall that inspects application traffic under a configured policy.'],['OSINT','Analysis based on public or lawfully accessible information, subject to privacy, scope, and terms.'],['OSCP / CEH','Provider credentials; their objectives, prerequisites, and status must be checked with the issuer.'],['Reverse / bind connection','Connection directions relative to a listener; command execution is an additional capability.'],['Persistence','A way access or execution survives a restart or other lifecycle event; study detection and cleanup.'],['SAST / DAST / SCA','Static code analysis, runtime application testing, and software-composition analysis: complementary methods.'],['SBOM','An inventory of software components; useful context rather than proof that a product is secure.'],['Honeypot','An intentionally instrumented decoy used to study or detect interactions.'],['Deauthentication','A wireless management operation that can affect connectivity; unsolicited disruption is outside these exercises.'],['Prompt injection','Untrusted content attempting to redirect an AI application’s behavior.'],['Chain of custody','A documented record of evidence acquisition, handling, access, and transfer.']
];
